-- Timu schema (SQLite). Applied by src/lib/db.ts on first open; later changes go in db/migrations.
-- Ids are RFC 4122 UUIDs generated by the app. Timestamps are ISO 8601 UTC strings, the same
-- format as Date#toISOString(), so they sort and compare as text.
-- Columns declared `json` hold JSON text and `boolean` hold 0/1; db.ts decodes both on read.
-- Every table carries owner_id so per-user data is an additive change later.

create table companies (
  id text primary key,
  owner_id text,
  slug text not null unique,
  name text not null,
  description text not null default '',
  emoji text not null default '🏢',
  color text not null default '#0ea5e9',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create table projects (
  id text primary key,
  owner_id text,
  company_id text references companies(id) on delete set null,
  slug text not null unique,
  name text not null,
  description text not null default '',
  emoji text not null default '📁',
  color text not null default '#6366f1',
  -- A named office theme for the project's floor.
  theme text not null default 'sunny',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create table teams (
  id text primary key,
  owner_id text,
  project_id text not null references projects(id) on delete cascade,
  name text not null,
  description text not null default '',
  color text not null default '#f59e0b',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  unique (project_id, name)
);

-- An agent is a "team member": a persona that owns a stream of Claude sessions.
create table agents (
  id text primary key,
  owner_id text,
  team_id text not null references teams(id) on delete cascade,
  name text not null,
  role text not null,
  persona text not null default '',
  -- Inputs to the SVG character kit: { seed, prop, skin?, hair?, hairColor?, outfit?, glasses? }
  avatar json not null default '{}',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  unique (team_id, name)
);

create table goals (
  id text primary key,
  owner_id text,
  project_id text not null references projects(id) on delete cascade,
  team_id text references teams(id) on delete set null,
  title text not null,
  description text not null default '',
  status text not null default 'active' check (status in ('active', 'achieved', 'dropped')),
  due_date text,
  priority text not null default 'normal' check (priority in ('low', 'normal', 'high')),
  achieved_at text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

create table goal_milestones (
  id text primary key,
  owner_id text,
  goal_id text not null references goals(id) on delete cascade,
  title text not null,
  done boolean not null default 0,
  done_at text,
  position integer not null default 0,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index goal_milestones_goal_idx on goal_milestones (goal_id, position);

create table sessions (
  id text primary key,
  owner_id text,
  source text not null check (source in ('cloud', 'local', 'claude_ai')),
  external_id text not null,
  title text not null default 'Untitled session',
  -- Sessions you rename keep your title on re-import.
  title_locked boolean not null default 0,
  url text,
  repo text,
  branch text,
  -- Normalised activity state across sources.
  status text not null default 'idle'
    check (status in ('working', 'needs_you', 'review', 'idle', 'done', 'failed')),
  status_detail text,
  first_user_message text,
  last_message text,
  last_message_role text check (last_message_role in ('user', 'assistant')),
  message_count integer not null default 0,
  started_at text,
  last_activity_at text,
  raw json not null default '{}',
  project_id text references projects(id) on delete set null,
  team_id text references teams(id) on delete set null,
  agent_id text references agents(id) on delete set null,
  goal_id text references goals(id) on delete set null,
  summary text,
  classified_at text,
  -- Archived sessions stay hidden and are never re-filed.
  archived boolean not null default 0,
  -- Latest triage verdict: { needed, kind, confidence, engine, reason, at }
  triage json,
  imported_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  unique (source, external_id)
);
create index sessions_status_idx on sessions (status);
create index sessions_agent_idx on sessions (agent_id);
create index sessions_archived_idx on sessions (archived);
create index sessions_activity_idx on sessions (last_activity_at);

-- Things the user needs to do: session asks (origin status/classifier) or hand-written to-dos (origin manual).
-- A to-do may be assigned to a teammate (agent_id) or to you (agent_id null).
create table tasks (
  id text primary key,
  owner_id text,
  session_id text references sessions(id) on delete cascade,
  kind text not null default 'respond' check (kind in ('respond', 'review', 'decide', 'unblock', 'run', 'todo')),
  title text not null,
  detail text not null default '',
  status text not null default 'open' check (status in ('open', 'snoozed', 'done')),
  -- 'status': raised from the session's own state; 'classifier': Claude judged it needs the user; 'manual': a to-do.
  origin text not null default 'status' check (origin in ('status', 'classifier', 'manual')),
  snoozed_until text,
  -- last_activity_at of the session when this task was raised; new activity re-opens triage.
  raised_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  resolved_at text,
  agent_id text references agents(id) on delete set null,
  -- Deleting a project keeps your to-dos; they just lose their project.
  project_id text references projects(id) on delete set null,
  goal_id text references goals(id) on delete set null,
  due_date text,
  priority text not null default 'normal' check (priority in ('low', 'normal', 'high')),
  -- Why a task was raised (or kept): the triage verdict that judged it.
  judge json,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  check (origin = 'manual' or session_id is not null)
);
-- One open ask per session at most.
create unique index tasks_one_active_per_session on tasks (session_id) where status <> 'done';
create index tasks_status_idx on tasks (status);
create index tasks_goal_idx on tasks (goal_id);
create index tasks_agent_idx on tasks (agent_id);

-- A pending org proposal from the classifier, reviewed in the setup wizard before apply.
create table proposals (
  id text primary key,
  owner_id text,
  status text not null default 'draft' check (status in ('draft', 'applied', 'discarded')),
  engine text not null check (engine in ('claude', 'heuristic')),
  body json not null,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  applied_at text
);

create table import_runs (
  id text primary key,
  owner_id text,
  source text not null,
  started_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  finished_at text,
  imported integer not null default 0,
  updated integer not null default 0,
  error text
);

create table settings (
  key text primary key,
  value json not null,
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);

-- Notes on any entity.
create table comments (
  id text primary key,
  owner_id text,
  entity_type text not null check (entity_type in ('company', 'project', 'team', 'agent', 'goal', 'session', 'task')),
  entity_id text not null,
  body text not null check (length(trim(body)) > 0),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index comments_entity_idx on comments (entity_type, entity_id, created_at);

-- Comments point at rows in several tables, so a foreign key can't clean them up.
-- These triggers delete an entity's comments with it (including cascaded deletes).
create trigger companies_comments_cleanup after delete on companies begin delete from comments where entity_type = 'company' and entity_id = old.id; end;
create trigger projects_comments_cleanup after delete on projects begin delete from comments where entity_type = 'project' and entity_id = old.id; end;
create trigger teams_comments_cleanup after delete on teams begin delete from comments where entity_type = 'team' and entity_id = old.id; end;
create trigger agents_comments_cleanup after delete on agents begin delete from comments where entity_type = 'agent' and entity_id = old.id; end;
create trigger goals_comments_cleanup after delete on goals begin delete from comments where entity_type = 'goal' and entity_id = old.id; end;
create trigger sessions_comments_cleanup after delete on sessions begin delete from comments where entity_type = 'session' and entity_id = old.id; end;
create trigger tasks_comments_cleanup after delete on tasks begin delete from comments where entity_type = 'task' and entity_id = old.id; end;
